INSERT INTO "public"."activities" ("created_at", "title", "shortDescription", "date", "participants", "id") VALUES
	('2025-03-08 07:55:58.975071+00', 'Getting started with Git and Docker', 'A introductory workshop on basics of Git and Docker with a little of C programming', '05/09/2024', 60, 'b8831f7f-ccf8-4b0d-8fb6-f155fff5a7b6'),
	('2025-03-08 07:56:46.902305+00', 'Python Programming for Machine Learning', 'Introduction to Machine Learning using Python', '28/12/2024', 60, '6fd92b55-1d14-4a84-975a-9a225e0652c2'),
	('2025-03-08 07:56:22.006096+00', 'Introduction to CAD', 'A introductory workshop on basics of CAD', '22/10/2024', 55, 'fbb184e9-652b-4b15-9bb2-9086410742cc'),
	('2025-09-14 04:33:13.034856+00', 'Playing With Arduinos', 'An introductory Arduino workshop for freshers, covering basics like LED blinking, servo control, and ultrasonic sensors, aimed at sparking interest in robotics and hands-on electronics.', '12/09/2025', 80, 'd444610f-905c-4893-bbb8-232b15adb782'),
	('2025-10-02 00:26:51.267627+00', 'Basics of Electronics and Soldering', 'The workshop introduced students to the fundamentals of electronics and hands-on soldering.Participants learned about the working of the 555 Timer IC, basic circuit design, and practical soldering techniques, gaining both theoretical knowledge and valuable hardware skills.  ', '30/09/2025', 100, 'a6e307ac-d8e1-4226-aa7a-268ec0e13d87');
