INSERT INTO "public"."events" ("created_at", "title", "description", "date", "time", "location", "capacity", "id", "attendanceOpen", "formConfigJson", "registrationOpen", "attendanceFormConfigJson") VALUES
	('2025-09-26 15:24:50.801641+00', 'Basic Electronics And Soldering Workshop', '<p><strong>Unlock the world of electronics!</strong> The <strong>Robotics Society of PEC</strong> is proud to present a foundational workshop designed specifically for <strong>1st-year students</strong> with zero prior experience.</p><p>This hands-on session will demystify the core concepts of <strong>basic electronics</strong>, from understanding fundamental components like <strong>resistors</strong>, <strong>capacitors</strong>, and <strong>LEDs</strong> to reading circuit diagrams. You’ll also master the crucial skill of <strong>soldering</strong>. Learn proper technique, safety best practices, and leave the session with the confidence to build and repair your own circuits.</p><p>It’s the perfect launchpad for anyone aspiring to dive into Robotics, IoT, or practical engineering. <strong>No prior knowledge is required.</strong> All materials and necessary equipment will be provided.</p><p><strong>Secure your spot and start your engineering journey today!</strong></p>', '30/09/2025', '05:00 PM-08:00 PM', 'L-22,23', 80, '4a5fe726-a96c-4815-be93-87dff234d62a', false, NULL, false, '{}'),
	('2025-10-01 15:40:54.328081+00', 'Blog-a-thon', '<h2>⏰ 48 Hours. 4 Winners. No Second Chances.</h2><p>Think you’ve got what it takes? 🖊️💡</p><p>🤖 Robotics Society presents: Intra PEC Blog Writing Contest</p><p>From personal notes ➝ to our official website! 🌐✨</p><ul><li><p>👑 Only the strongest 4 will shine.</p></li><li><p>🌟 Win visibility, credibility &amp; bragging rights.</p></li><li><p>📌 Submit before 2/10/2025 | 11:59 PM</p></li></ul><p>Rule book : https://docs.google.com/document/d/1eaSaL793kxPNP1K3IGJcvPKC2qhO5TgMfKKplLYayBM/edit?usp=drivesdk</p>', '01/10/2025', '12:01 AM-11:59 PM', 'online', 500, '332e6041-fb2c-41b1-afe9-162f554a2706', false, NULL, false, '{}'),
	('2025-10-01 15:41:34.561045+00', 'Blog-a-thon', '<h2>⏰ 48 Hours. 4 Winners. No Second Chances.</h2><p>Think you’ve got what it takes? 🖊️💡</p><p>🤖 Robotics Society presents: Intra PEC Blog Writing Contest</p><p>From personal notes ➝ to our official website! 🌐✨</p><ul><li><p>👑 Only the strongest 4 will shine.</p></li><li><p>🌟 Win visibility, credibility &amp; bragging rights.</p></li><li><p>📌 Submit before 2/10/2025 | 11:59 PM</p></li></ul><p>Rule book : https://docs.google.com/document/d/1eaSaL793kxPNP1K3IGJcvPKC2qhO5TgMfKKplLYayBM/edit?usp=drivesdk</p>', '02/10/2025', '12:01 AM-11:59 PM', 'online', 500, 'eb173d54-3b78-4618-9ca8-13f18558f5e7', false, NULL, false, '{}'),
	('2026-09-08 18:17:05.121742+00', 'Tech Talk Episode 1', '<p>Welcome to the first episode of TECH TALKS, a live technology show by the Robotics Society, PEC — built around conversations, demonstrations, ideas, and the technologies shaping what comes next.</p>', '09/09/2026', '05:00 PM-08:00 PM', 'Auditorium', 300, '780ea343-a022-4502-9b1b-a8a3a68e5634', false, NULL, false, '{}'),
	('2026-09-22 17:06:32.657155+00', '🤖 Robotics Society Workshop: ESP32 & IoT Systems', '<h1>🤖 Robotics Society Workshop: ESP32 &amp; IoT Systems</h1><p>Robotics Society is here with its first hands-on workshop this semester!</p><p><strong>ESP32 and IoT based systems</strong></p><p>📆 <strong>Date:</strong> 26th September 2026 (Saturday)</p><p>🚀 Learn. Build. Code. Innovate.</p><p>Join our hands-on workshop and get practical experience in:</p><ul><li><p> 🔹 ESP32 Programming &amp; Interfacing</p></li><li><p> 🔹 Sensors, Actuators &amp; Motor Control</p></li><li><p> 🔹 IoT &amp; Wireless Communication</p></li><li><p> 🔹 Robotics &amp; Hardware Implementation</p></li></ul><h2> 🎒 Optional Robotics Kit — ₹930</h2><p><strong>Kit includes:</strong></p><ul><li><p> ESP32 Development Board</p></li><li><p>Jumper Wires</p></li><li><p>Micro-USB Cable</p></li><li><p>LEDs (5)</p></li><li><p>Resistors (220Ω, 470Ω)</p></li><li><p>IR Sensor</p></li><li><p>Motion Sensor</p></li><li><p>MQ-7 Smoke Sensor</p></li><li><p>9g Servo Motor</p></li><li><p>Other required components</p></li></ul><blockquote><p>⏰ Forms for the ESP Kit close on <strong>24th night</strong>.</p></blockquote>', '26/09/2026', '05:00 PM-07:00 PM', 'L22, L23', 250, 'c5cd1f41-1f53-4900-b762-36e51380ad7a', true, '{"sections": [{"fields": [{"name": "field_1790181484292", "type": "text", "label": "Name", "required": true}, {"name": "field_1790226541034", "type": "text", "label": "Testing", "required": false}]}]}', true, '{"sections": [{"fields": [{"name": "field_1790244309589", "type": "text", "label": "What did you like?", "required": true}, {"name": "field_1790244713330", "type": "text", "label": "Any Suggestions?", "required": false}]}]}');
