INSERT INTO "public"."projects" ("created_at", "title", "description", "longDescription", "category", "technologies", "image", "id") VALUES
	('2025-03-07 19:10:55.433539+00', 'Robotic Arm', 'A mechanical arm mimicking human motion for automation and precision tasks.', 'A robotic arm is a programmable mechanical device designed to mimic the movements of a human arm. It consists of interconnected segments, joints, and actuators that enable precise motion and manipulation of objects. Controlled via computers, sensors, or AI, robotic arms are widely used in industries such as manufacturing, healthcare, and space exploration. They perform tasks like welding, assembly, surgery, and material handling with high accuracy and efficiency. Advanced models incorporate machine learning and vision systems for autonomous operation. Robotic arms enhance productivity, reduce human effort in hazardous environments, and play a crucial role in automation and modern robotics.', 'Automation', 'AI,Control Systems,Sensors', 'https://bkbmdjdypixbskuvrkxi.supabase.co/storage/v1/object/public/media/projects/roboticarm.jpg', '01f29edc-3a23-49db-ab75-b9c628e57e30'),
	('2025-03-07 19:10:07.139445+00', 'Robo Wars', 'Robo Wars is a combat competition where robots fight for victory.', '<h3>Robowar</h3><p></p><p>Robo Wars is a thrilling combat robotics competition where teams design, build, and battle remote-controlled robots in an enclosed arena. The objective is to disable opponents using weapons, strategy, and durability while adhering to weight and safety regulations. These battles test engineering skills, innovation, and teamwork as participants develop robots with powerful weaponry like spinners, flippers, and hammers. Popular worldwide, Robo Wars fosters STEM learning by encouraging mechanical design, electronics, and programming. Events range from university contests to global championships, captivating audiences with intense robot duels. The competition showcases cutting-edge technology and pushes the boundaries of robotic combat engineering.</p>', 'Combat Robotics', 'Mechanical Design,Electronics,Remote Control', 'https://bkbmdjdypixbskuvrkxi.supabase.co/storage/v1/object/public/media/projects/robowars.jpg', 'b2b3b78e-7c39-4399-8ba4-0ab9891a2df1'),
	('2025-03-07 19:09:17.186899+00', 'CanSat', 'CanSat by AAS is a mini satellite competition for educational purposes', '<h3>Cansat</h3><p><br>The CanSat competition by the American Astronautical Society (AAS) is an annual student design-build-launch competition that challenges teams to develop a small satellite system within a soda can-sized container. Participants must design a payload capable of executing a specific mission, including telemetry transmission, deployment mechanisms, and sensor data collection during descent. The competition simulates a real satellite mission, incorporating constraints on size, weight, and functionality. It fosters skills in engineering, programming, and teamwork while providing hands-on aerospace experience. CanSat is an excellent platform for students to gain practical knowledge in space technology and systems engineering.</p>', 'Aerospace', 'Telemetry,Sensors,Embedded Systems', 'https://bkbmdjdypixbskuvrkxi.supabase.co/storage/v1/object/public/media/projects/cansat.jpg', 'f95b4f8f-7310-4ec5-8174-d6aaa4e1bc70');
